import { computeLineOperations, splitLines } from './diffPatch.js'

/**
 * Perform a line-based three-way semantic merge.
 *
 * @param {string} base The original text at the time the AI draft was generated.
 * @param {string} live The current live text in the collaborative workspace.
 * @param {string} proposal The proposed text generated by AI.
 * @returns {{
 *   status: 'clean' | 'auto_merged' | 'conflict',
 *   hasConflict: boolean,
 *   mergedText: string,
 *   conflicts: Array<{
 *     startLine: number,
 *     baseContent: string,
 *     liveContent: string,
 *     proposalContent: string,
 *   }>
 * }}
 */
export function threeWayMerge(base, live, proposal) {
  // Case 1: Proposal is identical to base (no proposed changes)
  if (proposal === base) {
    return {
      status: 'clean',
      hasConflict: false,
      mergedText: live,
      conflicts: [],
    }
  }

  // Case 2: Live document has not changed since base
  if (live === base) {
    return {
      status: 'clean',
      hasConflict: false,
      mergedText: proposal,
      conflicts: [],
    }
  }

  // Case 3: Live document and proposal made identical changes
  if (live === proposal) {
    return {
      status: 'clean',
      hasConflict: false,
      mergedText: live,
      conflicts: [],
    }
  }

  // Case 4: Concurrent modifications occurred. Perform 3-way line alignment.
  const baseLines = splitLines(base)
  const liveOps = computeLineOperations(base, live)
  const proposalOps = computeLineOperations(base, proposal)

  // Map edits to base line numbers
  const liveChanges = extractHunksByBase(baseLines.length, liveOps)
  const proposalChanges = extractHunksByBase(baseLines.length, proposalOps)

  const mergedLines = []
  const conflicts = []
  let baseIdx = 0

  while (baseIdx < baseLines.length || hasRemainingEdits(liveChanges, baseIdx) || hasRemainingEdits(proposalChanges, baseIdx)) {
    const liveEdit = liveChanges.get(baseIdx)
    const propEdit = proposalChanges.get(baseIdx)

    if (!liveEdit && !propEdit) {
      // Neither modified this base line
      if (baseIdx < baseLines.length) {
        mergedLines.push(baseLines[baseIdx])
      }
      baseIdx++
      continue
    }

    if (liveEdit && !propEdit) {
      // Only live modified this section
      for (const ins of liveEdit.inserted) {
        mergedLines.push(ins)
      }
      baseIdx += Math.max(1, liveEdit.deletedCount)
      continue
    }

    if (!liveEdit && propEdit) {
      // Only proposal modified this section
      for (const ins of propEdit.inserted) {
        mergedLines.push(ins)
      }
      baseIdx += Math.max(1, propEdit.deletedCount)
      continue
    }

    // Both modified at this position!
    const liveInsStr = liveEdit.inserted.join('\n')
    const propInsStr = propEdit.inserted.join('\n')

    if (liveInsStr === propInsStr && liveEdit.deletedCount === propEdit.deletedCount) {
      // Identical concurrent changes
      for (const ins of liveEdit.inserted) {
        mergedLines.push(ins)
      }
      baseIdx += Math.max(1, liveEdit.deletedCount)
      continue
    }

    // Conflicting concurrent modifications
    const conflictBaseLines = baseLines.slice(baseIdx, baseIdx + Math.max(liveEdit.deletedCount, propEdit.deletedCount))
    const baseContent = conflictBaseLines.join('\n')
    const liveContent = liveInsStr
    const proposalContent = propInsStr

    conflicts.push({
      startLine: mergedLines.length + 1,
      baseContent,
      liveContent,
      proposalContent,
    })

    // Output Git-style conflict markers
    mergedLines.push('<<<<<<< LIVE (CURRENT WORKSPACE)')
    for (const l of liveEdit.inserted) mergedLines.push(l)
    mergedLines.push('=======')
    for (const p of propEdit.inserted) mergedLines.push(p)
    mergedLines.push('>>>>>>> AI PROPOSAL')

    baseIdx += Math.max(1, liveEdit.deletedCount, propEdit.deletedCount)
  }

  const hasConflict = conflicts.length > 0
  return {
    status: hasConflict ? 'conflict' : 'auto_merged',
    hasConflict,
    mergedText: mergedLines.join('\n'),
    conflicts,
  }
}

function hasRemainingEdits(map, currentBaseIdx) {
  for (const key of map.keys()) {
    if (key >= currentBaseIdx) return true
  }
  return false
}

/**
 * Helper to cluster diff operations by base line index.
 */
function extractHunksByBase(baseLength, operations) {
  const changes = new Map()
  let baseLine = 0

  for (let i = 0; i < operations.length; i++) {
    const op = operations[i]

    if (op.type === 'equal') {
      baseLine++
    } else if (op.type === 'delete') {
      const startBase = baseLine
      let deletedCount = 0
      const inserted = []

      while (i < operations.length && operations[i].type === 'delete') {
        deletedCount++
        baseLine++
        i++
      }
      while (i < operations.length && operations[i].type === 'insert') {
        inserted.push(operations[i].text)
        i++
      }
      i-- // Step back because outer loop increments
      changes.set(startBase, { deletedCount, inserted })
    } else if (op.type === 'insert') {
      const startBase = baseLine
      const inserted = []
      while (i < operations.length && operations[i].type === 'insert') {
        inserted.push(operations[i].text)
        i++
      }
      i--
      changes.set(startBase, { deletedCount: 0, inserted })
    }
  }

  return changes
}
